import{_ as s,o as n,c as e,ae as l}from"./chunks/framework.DFTT1zkb.js";const u=JSON.parse('{"title":"谨防诈骗","description":"","frontmatter":{},"headers":[],"relativePath":"begin/anti_fraud.md","filePath":"begin/anti_fraud.md"}'),i={name:"begin/anti_fraud.md"};function t(p,a,o,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="谨防诈骗" tabindex="-1">谨防诈骗 <a class="header-anchor" href="#谨防诈骗" aria-label="Permalink to &quot;谨防诈骗&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>不点击短信、消息、邮件中的不明链接</li><li>不随意相信陌生电话</li><li>无法判断或疑似被诈骗<strong>请及时联系辅导员、或者拨打报警电话</strong></li></ul></div><h2 id="常见骗局" tabindex="-1">常见骗局 <a class="header-anchor" href="#常见骗局" aria-label="Permalink to &quot;常见骗局&quot;">​</a></h2><h3 id="食堂-商场门口推销" tabindex="-1">食堂/商场门口推销 <a class="header-anchor" href="#食堂-商场门口推销" aria-label="Permalink to &quot;食堂/商场门口推销&quot;">​</a></h3><p>常自称学长或学姐的人以需要完成实习任务、社会实践等为理由在食堂或商场等区域要求同学下载xx软件、注册xx账号等，或者推销价格离谱的中性笔等，此类人员多为社会人士伪装而非真正的学生，请注意甄别</p><h3 id="进群邀请" tabindex="-1">进群邀请 <a class="header-anchor" href="#进群邀请" aria-label="Permalink to &quot;进群邀请&quot;">​</a></h3><p>加入 QQ 群聊后常收到进群邀请，如<code>大学宝藏资源库1️⃣群</code>、<code>ACG、绘画设计交流</code>、<code>20xx级变成python算法</code>、<code>🌸xx级新生避风港</code>、<code>xx准大一必备技能资料</code>等，此类群聊多为卖课或诈骗，请勿点击</p><h3 id="电子邮件" tabindex="-1">电子邮件 <a class="header-anchor" href="#电子邮件" aria-label="Permalink to &quot;电子邮件&quot;">​</a></h3><p>形如：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>尊敬的学员: *2025个人学分学籍通知:</span></span>
<span class="line"><span>http://********/.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span>学分状态直接影响您的毕业，请及时处理,因查询人数过多，请耐心等待2-3分钟</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(备注:请复制链接到浏览器打开登陆查看)</span></span></code></pre></div><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《学院通知》温馨提示:学生个人学籍档案信息核对安全登记最新通知(请务必核对个人信息录入系统，)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>感谢同学们的配合。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>http://********.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[请复制链接到浏览器查阅]</span></span></code></pre></div><p>一般来说，<strong>学校不会以邮件形式向学生发送通知</strong>，请勿点击邮件中的陌生链接，并及时联系辅导员核实确认</p><h2 id="其他形式" tabindex="-1">其他形式 <a class="header-anchor" href="#其他形式" aria-label="Permalink to &quot;其他形式&quot;">​</a></h2><ul><li>交易游戏账号（付款后被拉黑）</li><li>刷单兼职（要求支付一定的押金、学费或信息费后被拉黑）</li><li>冒充校领导、辅导员（发布不实消息，如交学费、关注公众号等）</li><li>色情果聊</li><li>网络交友诱导投资赌博（杀猪盘）</li><li>出租银行卡或电话卡（此行为可能涉嫌犯罪）</li><li>...</li></ul>`,14)])])}const b=s(i,[["render",t]]);export{u as __pageData,b as default};
